*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141e;
  --border-default: #2e3348;
  --border-focus:   #6c8aff;
  --border-error:   #ff5a6e;
  --text-primary:   #e8eaf2;
  --text-secondary: #8b90a8;
  --text-placeholder: #565c7a;
  --accent:         #6c8aff;
  --accent-hover:   #7f9aff;
  --error:          #ff5a6e;
  --success:        #43d98e;
  --ring-focus:     rgba(108, 138, 255, 0.35);
  --ring-error:     rgba(255, 90, 110, 0.25);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

html { font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 80px;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 8px;
  padding: 8px 12px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: 4px;
  z-index: 9999;
  text-decoration: none;
  white-space: nowrap;
}
.skip-link:focus { top: 8px; }

/* ── Card ── */
.support-card {
  width: 100%;
  max-width: 520px;
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 16px;
  padding: 40px 40px 44px;
}

/* ── Header ── */
.card-header { margin-bottom: 32px; }

.card-header .icon-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: rgba(108, 138, 255, 0.15);
  margin-bottom: 16px;
}

.card-header .icon-wrap svg {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: var(--accent);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--text-primary);
}

.card-header p {
  margin-top: 6px;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ── Form ── */
.contact-form { display: flex; flex-direction: column; gap: 20px; }

/* ── Field wrapper ── */
.form-field { display: flex; flex-direction: column; gap: 6px; }

.form-field label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.required-star {
  color: var(--error);
  font-weight: 700;
  line-height: 1;
  aria-hidden: true; /* handled via aria-required on the input */
}

/* ── Input ── */
.form-field input {
  width: 100%;
  padding: 11px 14px;
  background: var(--bg-input);
  border: 1.5px solid var(--border-default);
  border-radius: 8px;
  font-family: var(--font);
  font-size: 0.9375rem;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  /* Transparent outline for forced-colors focus */
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.form-field input::placeholder { color: var(--text-placeholder); }

.form-field input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--ring-focus);
  outline: 2px solid var(--border-focus);
}

.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}
.form-field input[aria-invalid="true"]:focus {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px var(--ring-error);
  outline-color: var(--border-error);
}

/* ── Helper / error text ── */
.field-hint {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--error);
  display: flex;
  align-items: center;
  gap: 5px;
  line-height: 1.4;
}

.field-error svg {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  fill: none;
  stroke: var(--error);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Submit button ── */
.btn-submit {
  margin-top: 8px;
  width: 100%;
  padding: 13px 20px;
  background: var(--accent);
  color: #fff;
  font-family: var(--font);
  font-size: 0.9375rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s;
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.btn-submit:hover { background: var(--accent-hover); }

.btn-submit:focus-visible {
  outline: 2px solid var(--border-focus);
  box-shadow: 0 0 0 4px var(--ring-focus);
}

.btn-submit:active { opacity: 0.9; }

/* ── Success banner ── */
.success-banner {
  display: none;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  background: rgba(67, 217, 142, 0.1);
  border: 1px solid rgba(67, 217, 142, 0.3);
  border-radius: 8px;
  font-size: 0.9rem;
  color: var(--success);
  line-height: 1.5;
}
.success-banner.visible { display: flex; }

.success-banner svg {
  flex-shrink: 0;
  margin-top: 1px;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: var(--success);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Live region ── */
#form-status { clip: rect(0 0 0 0); position: absolute; width: 1px; height: 1px; overflow: hidden; }

/* ── Forced colors ── */
@media (forced-colors: active) {
  .form-field input {
    border-color: ButtonBorder;
    background: Canvas;
    color: CanvasText;
    forced-color-adjust: none;
  }
  .form-field input:focus { outline-color: Highlight; }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonBorder;
    forced-color-adjust: none;
  }
  .field-error { color: LinkText; }
}

/* ── Reflow / responsive ── */
@media (max-width: 540px) {
  .support-card { padding: 28px 20px 36px; border-radius: 12px; }
  .card-header h1 { font-size: 1.25rem; }
}
